"""Procedures Module"""

from __future__ import annotations

import datetime
import logging
import threading
import time

from netconf_client.ncclient import Notification
from taf.ul.oran_mplane.core.communication import Communication


class SupervisionMonitoringError(Exception):
    """Exception used in supervision monitoring procedures"""


class Procedures:
    """Procedures class"""

    def __init__(self, communication: Communication, logger=None):
        self.logger = logging.getLogger(__name__) if logger is None else logger
        self.communication = communication
        self.validation = communication.validation
        self.supervision_threads = {}
        self.supervision_stop_events = {}

    def _send_rpc_supervision_watchdog_reset(
        self,
        session,
        supervision_notification_interval,
        guard_timer_overhead,
        logger=None,
        odu_id: str | None = None,
    ) -> str:
        msg = {
            "request": {
                "supervision-watchdog-reset": {
                    "@xmlns": "urn:o-ran:supervision:1.0",
                    "supervision-notification-interval": supervision_notification_interval,
                    "guard-timer-overhead": guard_timer_overhead,
                }
            },
            "expected_response": "</next-update-at>",
        }
        if odu_id is not None:
            msg["request"]["supervision-watchdog-reset"]["context"] = {"odu-id": odu_id}
        _timestamp, out = self.communication.send_rpc(
            session, msg, "dictionary", logger=logger, validation_mode="string"
        )
        return out

    def _collect_supervision_notification(
        self,
        session: str,
        timeout: int | float,
        stop_event: threading.Event | None = None,
        logger: logging.Logger | None = None,
    ) -> Notification:
        """
        Wait for a supervision notification until timeout or stop_event is set.

        This method is used for the netconf monitoring thread to collect supervision notifications. It shouldn't be
        opened to the interface and used manually.

        :param session: Session name.
        :param timeout: Timeout in seconds.
        :param stop_event: Event to stop waiting.
        :param logger: Alternative logger for multithreaded execution.
        """
        logger = logger or self.logger
        stop = datetime.datetime.now() + datetime.timedelta(seconds=timeout)
        while datetime.datetime.now() < stop and (not stop_event or not stop_event.is_set()):
            self.communication.collect_all_notifications(session, stop_event)
            if self.communication.supervision_buffer[session]:
                notification = self.communication.supervision_buffer[session].pop(0)
                logger.debug(f"Collected supervision notification:\n{notification.notification_xml}")
                return notification
            # Add sleep 10ms to prevent busy-wait loop from freezing the CPU
            time.sleep(0.01)
        if not stop_event or not stop_event.is_set():
            msg = (
                f"Timeout reached while waiting for supervision notification for {session}. Procedure will be stopped."
            )
            if stop_event:
                logger.error(msg)
            raise SupervisionMonitoringError(msg)

    # pylint: disable=too-many-arguments
    # pylint: disable=too-many-locals
    def monitoring_netconf_connectivity(  # noqa: C901
        self,
        session: str,
        supervision_notification_interval: int,
        guard_timer_overhead: int,
        loops: int,
        set_max_interval_in_last_loop: bool,
        delta_time: int,
        skip_first_notification: bool,
        validate_timestamps: bool,
        validate_session_id: bool,
        odu_id: str | None = None,
    ) -> None:
        """This method describes "3.6 Monitoring NETCONF connectivity" from
        O-RAN Alliance Working Group 4 - Management Plane Specification
        :param session: string value example: "session1"
        :param supervision_notification_interval: timer for sending supervision-notification by RU
        :param guard_timer_overhead: timer for sending supervision-watchdog-reset by DU
        :param loops: number of loops to perform monitoring for
        :param set_max_interval_in_last_loop: boolean, if set to True max value for both timers will
                                              be set on last loop to ~36h hours
        :param delta_time: timestamp comparison accuracy in seconds
        :param skip_first_notification: boolean, if True makes the method start with
                                        watchdog_reset instead of notification check
        :param validate_timestamps: boolean, if True makes the method validate timestamp format
                                    in received messages and check differences between consecutive
                                    ones
        :param odu_id: Optional ODU identifier to include in supervision-watchdog-reset RPC.
        :param validate_session_id: boolean, if True makes the method validate session-id in received messages
        """
        self._precondition_stop_monitoring_thread(session)
        timeout = 60 + delta_time
        max_unint16 = 65535
        messages = []
        success = True
        if skip_first_notification:
            rpc_reply = self._send_rpc_supervision_watchdog_reset(
                session, supervision_notification_interval, guard_timer_overhead, odu_id=odu_id
            )
            timeout = supervision_notification_interval + delta_time
            success = self.validation.get_valid_timestamp_from_xml(rpc_reply, "next-update-at") is not None
        current_notification_interval = supervision_notification_interval
        current_guard_timer_overhead = guard_timer_overhead
        for loop_id in range(1, loops + 1):
            self.logger.debug(f"Monitoring NETCONF connectivity loop: {loop_id}")
            if set_max_interval_in_last_loop:
                if loop_id == loops:
                    current_notification_interval = max_unint16
                    current_guard_timer_overhead = max_unint16
            notification = self._collect_supervision_notification(session=session, timeout=timeout)
            rpc_reply = self._send_rpc_supervision_watchdog_reset(
                session, current_notification_interval, current_guard_timer_overhead, odu_id=odu_id
            )
            messages.append(
                (
                    (notification if isinstance(notification, str) else notification.notification_xml),
                    rpc_reply,
                )
            )
            timeout = current_notification_interval + delta_time
            self.logger.debug(
                f"Timeout set to: {timeout} seconds due new values of"
                f" supervision_notification_interval: {current_notification_interval}"
                f" and guard_timer_overhead: {current_guard_timer_overhead}"
            )
        fail_msg = []
        if validate_timestamps:
            valid_timestamps = self.validation.validate_supervision_timestamps(
                messages,
                supervision_notification_interval,
                guard_timer_overhead,
                delta_time,
            )
            success = success and valid_timestamps
            fail_msg.append("Timestamp validation failed")
        if validate_session_id:
            success = success and self.validation.validate_session_id_from_xml(
                messages, self.communication.get_session_id(session=session)
            )
            fail_msg.append("Session-ID validation failed")
        if not success:
            raise SupervisionMonitoringError(" and ".join(fail_msg))


    def monitoring_netconf_connectivity_threaded(
        self,
        session: str,
        supervision_notification_interval: int,
        guard_timer_overhead: int,
        delta_time: int,
        threaded_logger: logging.Logger | None,
        odu_id: str | None = None,
    ) -> None:
        """Run a monitoring loop to continuously check for supervision notifications.

        This is a threaded implementation of ORAN WG4 MPlane Specification - 6.7 Monitoring NETCONF Connectivity.
        It is meant for continuous monitoring in the background, so it can handle small timer values.
        To stop a running monitoring thread, use the `stop_monitoring_thread` method.

        :param session: identifier of the session to monitor, e.g. "master_0". Should correspond to a valid session with
            a notification subscription established.
        :param supervision_notification_interval: the interval in seconds between notifications sent by the RU. Sent via
         the supervision-watchdog-reset RPC.
        :param guard_timer_overhead: additional time in seconds that the O-RU waits for a response from the O-DU after
            sending a supervision notification. Sent via the supervision-watchdog-reset RPC.
        :param delta_time: additional time in seconds to wait for the supervision notification to arrive. Not part of
         the specification, but added to account for network latency. Not sent via the supervision-watchdog-reset RPC.
        :param threaded_logger: logger object to use for logging in the monitoring thread. If None, messages will be
         logged to the default logger.
        :param odu_id: Optional ODU identifier to include in supervision-watchdog-reset RPC.
        """
        self._precondition_stop_monitoring_thread(session)
        stop_event = threading.Event()
        thread = threading.Thread(
            target=self._monitoring_thread_worker,
            args=(
                session,
                supervision_notification_interval,
                guard_timer_overhead,
                delta_time,
                stop_event,
                threaded_logger,
            ),
            kwargs={"odu_id": odu_id},
        )
        thread.start()
        self.supervision_threads[session] = thread
        self.supervision_stop_events[session] = stop_event

    def _precondition_stop_monitoring_thread(self, session: str) -> None:
        """Stop a running monitoring thread before running the procedure for the same session.

        :param session: identifier of the session to stop monitoring, e.g. "master_0".
        """
        if session in self.supervision_threads:
            self.logger.info(f"Netconf monitoring is already running for {session}. It will be stopped.")
            self.stop_monitoring_thread(session)

    def stop_monitoring_thread(self, session: str) -> None:
        """Stop a running monitoring thread for a specific session.

        :param session: identifier of the session to stop monitoring, e.g. "master_0".
        """
        if session in self.supervision_threads:
            self.supervision_stop_events[session].set()
            self.supervision_threads[session].join()
            del self.supervision_threads[session]
            del self.supervision_stop_events[session]

    def stop_all_monitoring_threads(self) -> None:
        """Stop all running monitoring threads."""
        for session in self.communication.sessions:
            self.stop_monitoring_thread(session)

    def _monitoring_thread_worker(
        self,
        session: str,
        supervision_notification_interval: int,
        guard_timer_overhead: int,
        delta_time: int,
        stop_event: threading.Event,
        logger: logging.Logger,
        odu_id: str | None = None,
    ) -> None:
        """Worker method to be used in a monitoring thread."""
        timeout = supervision_notification_interval + delta_time
        logger.debug(
            f"Starting monitoring thread for {session} with parameters: "
            f"{supervision_notification_interval=}, {guard_timer_overhead=}, {delta_time=}"
        )
        try:
            while not stop_event.is_set():
                self._send_rpc_supervision_watchdog_reset(
                    session,
                    supervision_notification_interval,
                    guard_timer_overhead,
                    logger=logger,
                    odu_id=odu_id,
                )
                self._collect_supervision_notification(
                    session,
                    timeout=timeout,
                    stop_event=stop_event,
                    logger=logger,
                )
        finally:
            logger.debug(f"Stopped monitoring thread for {session}.")
